<script setup lang="ts">
import {ref} from 'vue'
import {api,post} from '../api'
import {usePolling} from '../usePolling'
import {number,time} from '../format'
type Status={mode:string;control:{version:string;activatedAt:string;rulesHash:string;parameters:{maximumPositions:number;maximumLeverage:number;riskFraction:number;pilotRiskScale:number;absoluteRiskCap:number;totalRiskFraction:number;absoluteTotalRiskCap:number}}|null;newPositions:number;oldPositions:number;pending:number;lateFundingAdjustment:number;funding:{positionId:string;symbol:string;status:string;knownThrough:string|null;checkedAt:string;reason:string}[];notices:string[]}
const data=ref<Status|null>(null),busy=ref(false),actionError=ref('');let generation=0
const {error}=usePolling(async signal=>{if(busy.value)return;const g=generation;const result=await api<Status>('/api/quant/execution',{signal});if(g===generation&&!busy.value)data.value=result},10000)
async function activate(){if(busy.value)return;generation++;busy.value=true;actionError.value='';try{data.value=await post<Status>('/api/quant/execution/activate')}catch(e){actionError.value=e instanceof Error?e.message:String(e)}finally{busy.value=false}}
const label=(s:string)=>({ExperimentalLiveSimulation:'模拟运行中',PausedEntries:'新仓暂停，持仓继续管理',NotActivated:'尚未启用',ObservedWindow:'已核对到延迟窗口',Partial:'覆盖未齐',Unknown:'来源不足',Pending:'待补证',Conflict:'来源冲突'}[s]??s)
</script>
<template><section class="detail quant-execution" aria-label="当前模拟执行状态"><div class="execution-title"><div><small>QUANT PAPER · VIRTUAL FUNDS</small><h2>当前模拟执行 · {{data?label(data.mode):'读取中'}}</h2></div><button v-if="data&&!data.control" class="replay-action" :disabled="busy" @click="activate">{{busy?'正在启用':'启用新模型模拟实验'}}</button></div><p v-if="error||actionError" role="alert">{{actionError||error}}</p>
<template v-if="data?.control"><p>{{data.control.version}} · 生效 {{time(data.control.activatedAt)}}。只接收生效后的完整前瞻信号，先保存意向，再等后续报价、标记价及盘口复核成交。</p><div class="execution-grid"><div>旧仓<strong>{{data.oldPositions}}</strong><small>沿开仓时原规则退出</small></div><div>新仓 / 意向<strong>{{data.newPositions}} / {{data.pending}}</strong><small>共同占用最多{{data.control.parameters.maximumPositions}}笔</small></div><div>新仓杠杆上限<strong>{{data.control.parameters.maximumLeverage}}倍</strong><small>结构较宽时降低杠杆或放弃</small></div><div>迟到资金费调整<strong>{{number(data.lateFundingAdjustment,6)}} U</strong><small>正数支出，负数收入；已纳入账户净额</small></div></div><p>新仓基准风险为权益约{{number(data.control.parameters.riskFraction*data.control.parameters.pilotRiskScale*100,2)}}%、最多{{number(data.control.parameters.absoluteRiskCap*data.control.parameters.pilotRiskScale,2)}} U，再随环境、OI和回撤降低。旧仓、相关仓位及意向继续占额度；不是有五个空位就能开满。</p>
<p class="radar-notice">这是未验证策略的虚拟实验。价格候选不等于成交；当前预览、过期信号、缺资料和组合额度不足均不会强制开仓。最近10分钟资金费暂记，缺窗/冲突时等待补证，风险退出继续。</p>
<details><summary>实际资金费覆盖与执行边界</summary><div class="table-scroll"><table><thead><tr><th>新仓/历史新仓</th><th>状态</th><th>来源覆盖</th><th>核对</th></tr></thead><tbody><tr v-for="f in data.funding" :key="f.positionId"><td>{{f.symbol}}</td><td>{{label(f.status)}}</td><td>{{time(f.knownThrough)}}</td><td>{{f.reason}}<small>{{time(f.checkedAt)}}</small></td></tr><tr v-if="!data.funding.length"><td colspan="4">尚无新模型持仓资金费样本。旧仓费用继续按旧模型记录，来源对照保留在执行基础中。</td></tr></tbody></table></div><p v-for="n in data.notices" :key="n" class="muted">{{n}}</p><small class="muted">规则SHA256 {{data.control.rulesHash}}</small></details></template><p v-else>启用会保留现有现金、旧仓和历史，仅迁移新开仓规则；须先完成旧待成交意向，策略仍未通过盈利验证。</p></section></template>
<style scoped>.execution-title{display:flex;align-items:center;justify-content:space-between;gap:18px;flex-wrap:wrap}.execution-title small{font-size:10px;color:#8aafa4;letter-spacing:1.5px}.execution-title h2{margin-top:8px}.execution-grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:12px;margin:18px 0}.execution-grid>div{padding:14px;background:#101b22;border:1px solid #30444e;border-radius:6px;font-size:12px}.execution-grid strong{display:block;font-size:23px;margin:10px 0}.execution-grid small,.muted{font-size:11px;color:#9bb2c2;overflow-wrap:anywhere}.quant-execution summary{cursor:pointer;margin-top:18px}.quant-execution td{white-space:normal;min-width:100px}@media(max-width:900px){.execution-grid{grid-template-columns:repeat(2,minmax(0,1fr))}}</style>
